const html = $json.data;
const webhookBody = $('Webhook do Changedetection').first().json.body;
const message = typeof webhookBody.message === 'string' ? JSON.parse(webhookBody.message) : webhookBody.message;
const diffText = message.diff || '';

// Parse de todos os itens do HTML
const items = [];
const regex = /<p><a[^>]*href=["']([^"']*)["'][^>]*>(.*?)<\/a>(?:<br\s*\/?>\s*([\s\S]*?))?<\/p>/gi;

let match;
while ((match = regex.exec(html)) !== null) {
  const href = match[1];
  const titleHtml = match[2];
  const descHtml = match[3] || '';

  if (href.includes('exibirArquivo')) {
    const title = titleHtml.replace(/<[^>]+>/g, '').trim();
    const desc = descHtml.replace(/<[^>]+>/g, '').trim();
    items.push({
      href: href.startsWith('http') ? href : `https://www.nfe.fazenda.gov.br/portal/${href.replace(/^portal\//, '')}`,
      relativeHref: href,
      title: title,
      desc: desc
    });
  }
}

// Extrair t├¡tulos removidos do diff
const lines = diffText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const removedTitles = [];
for (const line of lines) {
  if (line.startsWith('(removed)')) {
    const clean = line.replace(/^\(removed\)\s*/, '').trim();
    if (clean.includes('Nota T├⌐cnica') || clean.includes('NT') || clean.includes('Tabela') || clean.includes('IT') || clean.includes('Informe') || clean.includes('Schema') || clean.includes('Pacote') || clean.includes('Esquema')) {
      removedTitles.push(clean);
    }
  }
}

return [{
  json: {
    items: items,
    totalExtracted: items.length,
    portalTitle: message.title || 'Nota Fiscal Eletr├┤nica',
    portalUrl: message.url || 'https://www.nfe.fazenda.gov.br',
    diff: diffText,
    removedList: removedTitles
  }
}];

// Agrupa todos os bin├írios de todos os itens em um ├║nico item para o n├│ de E-mail
const allItems = $input.all();

const binaryData = {};
const docList = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const bin = item.binary || {};

  // Pegar qualquer bin├írio dispon├¡vel no item
  for (const binKey of Object.keys(bin)) {
    const file = bin[binKey];
    const newKey = `anexo_${i}`;
    binaryData[newKey] = file;
    docList.push({
      name: file.fileName || item.json.title || `Documento_${i+1}`,
      size: file.fileSize || ''
    });
  }
}

// Pegar dados do primeiro item para o contexto
const firstJson = allItems[0]?.json || {};

return [{
  json: {
    ...firstJson,
    docsDownloaded: docList,
    totalDocs: docList.length,
    attachmentKeys: Object.keys(binaryData).join(',')
  },
  binary: binaryData
}];

const filterResult = $input.first().json;
const context = $('Extrair Itens da P├ígina').first().json;

if (!filterResult.items || filterResult.items.length === 0) {
  // Zero documentos novos: encerra silenciosamente sem downloads ou envios
  return [];
}

if (filterResult.circuit_breaker) {
  // Trava de P├ónico (mais de 10 docs): retorna item especial para alerta
  return [{
    json: {
      alertOnly: true,
      circuitBreaker: true,
      count: filterResult.count,
      portalTitle: context.portalTitle,
      portalUrl: context.portalUrl,
      removedList: context.removedList
    }
  }];
}

// Retorna cada documento aprovado para a esteira normal
return filterResult.items.map((doc, idx) => ({
  json: {
    ...doc,
    itemIndex: idx,
    totalItems: filterResult.items.length,
    portalTitle: context.portalTitle,
    portalUrl: context.portalUrl,
    diff: context.diff,
    removedList: context.removedList
  }
}));

const files=$input.all();
if(!files.length)throw new Error('Approved batch contains no PDF files');
const meta=$('Preparar Documentos para E-mail').all().map(i=>i.json);
if(meta.length!==files.length)throw new Error('Approved batch metadata does not match PDF files');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const binary={},documents=[];
for(let n=0;n<files.length;n++){
  const source=files[n].binary?.anexo_arquivo;
  if(!source)throw new Error('PDF binary missing for '+meta[n].title);
  binary['anexo_'+n]=source;
  documents.push({title:meta[n].title,date:meta[n].date,url:meta[n].url,file_path:meta[n].file_path,document_id:meta[n].document_id});
}
const fmt=d=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(d||'');return m?m[3]+'/'+m[2]+'/'+m[1]:esc(d);};
const rows=documents.map(i=>'<li style="margin:0 0 8px 0;"><b>[NOVO]</b> '+esc(i.title)+'</li>').join('');
const total=documents.length;
const head=total>1?total+' Atualizações Detectadas':'Atualização Detectada';
const html='<div style="font-family:\'Segoe UI\',Arial,sans-serif;max-width:680px;color:#2c3e50;line-height:1.6;">'
+'<div style="border-bottom:2px solid #00a88f;padding-bottom:10px;margin-bottom:16px;">'
+'<span style="background-color:#e6f7f5;color:#00806c;font-size:11px;font-weight:700;padding:4px 8px;border-radius:4px;text-transform:uppercase;letter-spacing:0.5px;">Monitoramento Automático • '+head+'</span>'
+'<h2 style="margin:8px 0 0 0;font-size:18px;color:#0b3c5d;">Portal da Nota Fiscal Eletrônica</h2></div>'
+'<p style="font-size:14px;margin:0 0 12px 0;">Foi detectada uma nova publicação oficial no portal monitorado. Foram anexados a este e-mail <b>'+total+' arquivo(s)</b> correspondente(s) às atualizações:</p>'
+'<div style="background-color:#f8fafc;border:1px solid #e2e8f0;border-left:4px solid #00a88f;border-radius:6px;padding:16px;margin-bottom:20px;font-size:14px;color:#1e293b;"><ul style="margin:0;padding-left:20px;list-style:none;">'+rows+'</ul></div>'
+'<div style="margin-bottom:28px;"><a href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" style="background-color:#0b3c5d;color:#ffffff;text-decoration:none;padding:10px 18px;border-radius:5px;font-size:13px;font-weight:600;display:inline-block;">Acessar Página Oficial &rarr;</a></div>'
+'<p>Atenciosamente,</p>'+"<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" style=\"width: 600px; max-width: 600px; background-color: #ffffff; border-collapse: collapse;\"><tr><td style=\"padding: 15px 0 10px 0;\"><table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse;\"><tr><td valign=\"middle\" width=\"140\" style=\"width: 140px; padding-right: 5px;\"><a href=\"https://exemplo.com.br\" target=\"_blank\" style=\"text-decoration: none;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/logo_mpl.png\"alt=\"MPL\"width=\"135\" height=\"30\"style=\"display: block; border: 0; outline: none; width: 135px; height: 30px;\" /></a></td><td valign=\"middle\" width=\"20\" style=\"width: 20px; text-align: center;\"><table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"55\" style=\"margin: 0 auto;\"><tr><td width=\"1\" style=\"width: 1px; background-color: #00376b; font-size: 1px; line-height: 1px;\">&nbsp;</td></tr></table></td><td valign=\"middle\" style=\"text-align: left; padding-left: 5px;\"><div style=\"font-family: 'Segoe UI', Helvetica, Arial, sans-serif; font-size: 20px; font-weight: bold; color: #00376b; line-height: 1.2; margin: 0;\">Equipe Fiscal / Consultoria</div><div style=\"font-family: 'Segoe UI', Helvetica, Arial, sans-serif; font-size: 14px; font-weight: 500; color: #00376b; line-height: 1.4; margin: 3px 0 0 0;\">Consultor Financeiro Sênior</div></td><td valign=\"top\" align=\"right\" style=\"text-align: right; white-space: nowrap;\"><a href=\"https://www.linkedin.com/company/mpl-corporate-software/\" target=\"_blank\" style=\"text-decoration: none;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/icon_linkedin.png\"alt=\"LinkedIn\"width=\"24\" height=\"24\"style=\"display: inline-block; border: 0; outline: none; width: 24px; height: 24px; margin-left: 5px;\" /></a><a href=\"https://www.instagram.com/mpl_corporate_software/\" target=\"_blank\" style=\"text-decoration: none;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/icon_instagram.png\"alt=\"Instagram\"width=\"24\" height=\"24\"style=\"display: inline-block; border: 0; outline: none; width: 24px; height: 24px; margin-left: 5px;\" /></a><a href=\"https://www.youtube.com/channel/UCVsLH6x9u-CF8R2yxLmvBZA/featured\" target=\"_blank\" style=\"text-decoration: none;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/icon_youtube.png\"alt=\"YouTube\"width=\"24\" height=\"24\"style=\"display: inline-block; border: 0; outline: none; width: 24px; height: 24px; margin-left: 5px;\" /></a><a href=\"https://exemplo.com.br/blog/\" target=\"_blank\" style=\"text-decoration: none;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/icon_blog.png\"alt=\"Blog\"width=\"24\" height=\"24\"style=\"display: inline-block; border: 0; outline: none; width: 24px; height: 24px; margin-left: 5px;\" /></a></td></tr></table></td></tr><tr><td style=\"padding: 8px 0 5px 0;\"><img src=\"https://exemplo.com.br/wp-content/uploads/2026/06/slogan.png\"alt=\"Inove com inteligência. Opere com segurança.\"width=\"565\" height=\"29\"style=\"display: block; border: 0; outline: none; width: 565px; height: 29px;\" /></td></tr></table>"+'</div>';
return [{json:{batch_id:files[0].json.batch_id||meta[0].batch_id,documents,totalDocs:total,attachmentKeys:Object.keys(binary).join(','),emailHtml:html},binary}];
